-- name: platform__workers_resolveintegrationinvocation_1 :one
SELECT r.id::text,n.id::text,c.id::text,g.id::text,r.project_id::text FROM control_plane.runs r JOIN control_plane.run_nodes n ON n.run_id=r.id JOIN control_plane.integration_connections c ON c.organization_id=r.organization_id AND c.ref=$4 AND c.enabled AND c.state='CONNECTED' JOIN control_plane.integration_grants g ON g.connection_id=c.id AND g.capability_key=$5 AND g.target_kind='AGENT' AND g.target_ref=(SELECT a.ref FROM control_plane.agents a WHERE a.id=n.agent_id) AND g.enabled WHERE r.organization_id=$1::uuid AND r.ref=$2 AND n.ref=$3 AND n.state='RUNNING' FOR UPDATE OF n,c,g
